}
function drawPerson(x,y,color,name,alien){ctx.fillStyle='#263a3c20';ctx.beginPath();ctx.ellipse(x,y+15,12,5,0,0,7);ctx.fill();ctx.fillStyle=alien?color:'#536c75';ctx.beginPath();ctx.roundRect(x-9,y-3,18,19,6);ctx.fill();ctx.fillStyle=alien?'#ddfff1':'#edc99e';ctx.beginPath();ctx.arc(x,y-8,8,0,7);ctx.fill();ctx.fillStyle='#27343e';ctx.beginPath();ctx.arc(x-3,y-9,1.3,0,7);ctx.arc(x+3,y-9,1.3,0,7);ctx.fill();ctx.fillStyle='#f9f5e8';ctx.font='9px "DM Sans",sans-serif';ctx.textAlign='center';ctx.fillText(name,x,y+29)}
function drawAlien(p,i){const x=p.x,y=p.y;ctx.fillStyle='#22363826';ctx.beginPath();ctx.ellipse(x,y+15,13,6,0,0,7);ctx.fill();ctx.fillStyle=p.color;ctx.beginPath();ctx.roundRect(x-10,y-4,20,22,7);ctx.fill();ctx.fillStyle='#f5d6b7';ctx.beginPath();ctx.ellipse(x,y-8,9,10,0,0,7);ctx.fill();ctx.fillStyle='#263846';ctx.beginPath();ctx.ellipse(x-3.3,y-8,2,3.8,0,0,7);ctx.ellipse(x+3.3,y-8,2,3.8,0,0,7);ctx.fill();ctx.fillStyle='#f2c86e';ctx.beginPath();ctx.arc(x,y-18,10,Math.PI,0);ctx.lineTo(x+8,y-15);ctx.lineTo(x-8,y-15);ctx.fill();ctx.fillStyle='#263846';ctx.font='600 9px "DM Sans",sans-serif';ctx.textAlign='center';ctx.fillText(p.name,x,y+31);if(i<selected){ctx.strokeStyle=p.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y-5,17,0,7);ctx.stroke()}}
function movePlayer(p,dx,dy,dt){const l=Math.hypot(dx,dy)||1;p.x=Math.max(24,Math.min(W-24,p.x+dx/l*160*dt));p.y=Math.max(24,Math.min(H-24,p.y+dy/l*160*dt));p.step+=dt*9;if(Math.abs(dx)>.01)p.facing=Math.sign(dx)}
function loop(now){if(!started)return;const dt=Math.min(.05,(now-last)/1000);last=now;if(!ended){time-=dt;if(time<=0){time=0;finish(trust>=65)}
players.forEach((p,i)=>{if(i<selected){let dx=0,dy=0,c=controls[i];if(c){const [up,left,down,right]=c.dir;dx=(keys.has(right)?1:0)-(keys.has(left)?1:0)+(touchDirs.has('right')?1:0)-(touchDirs.has('left')?1:0);dy=(keys.has(down)?1:0)-(keys.has(up)?1:0)+(touchDirs.has('down')?1:0)-(touchDirs.has('up')?1:0)}movePlayer(p,dx,dy,dt);p.job=Math.hypot(dx,dy)>.1?'En camino':'En calle';const st=document.getElementById('state'+i);if(st)st.textContent=Math.hypot(dx,dy)>.1?'EN CAMINO':'EN CALLE'}else{p.aiDelay-=dt;if(p.aiDelay<=0){const st=stations[(Math.floor(now/14000)+i)%stations.length];if(near(p,st,100)){if(Math.random()<.78){trust=Math.min(100,trust+7);suspicion=Math.max(0,suspicion-3);p.done++;p.job='Haciendo un turno';say(`${p.name} consiguió trabajo. +7 confianza.`)}else{suspicion=Math.min(100,suspicion+5);say(`${p.name} casi se delata…`)}p.aiDelay=13+i*3;updateHUD();checkEnd()}else{const dx=st.x-p.x,dy=st.y-p.y;movePlayer(p,dx,dy,dt*2);p.job='Buscando trabajo'}}else{const st=document.getElementById('state'+i);if(st)st.textContent=p.job==='Haciendo un turno'?'TRABAJANDO':'DE INCÓGNITO'}}});suspicion=Math.max(0,suspicion-dt*.24);updateHUD();const focus=players[0]||{x:W/2,y:H/2};const vw=canvas.clientWidth,vh=canvas.clientHeight;camera.x+=(Math.max(0,Math.min(W-vw,focus.x-vw/2))-camera.x)*Math.min(1,dt*4);camera.y+=(Math.max(0,Math.min(H-vh,focus.y-vh/2))-camera.y)*Math.min(1,dt*4)}drawWorld();if(!ended)requestAnimationFrame(loop)}
canvas.addEventListener('pointerdown',e=>{if(!started||activeTask)return;const r=canvas.getBoundingClientRect();const wx=e.clientX-r.left+camera.x,wy=e.clientY-r.top+camera.y;const s=stations.find(z=>Math.hypot(z.x-wx,z.y-wy)<48);if(s){const p=players.find(q=>q.human);if(p&&near(p,s,130))openTask(s,0);else say('Acércate para interactuar.')}});
updateHUD();drawWorld();
</script></body></html>

